package com.example.kyrgyzkeyboard.utils

import com.example.kyrgyzkeyboard.keyboard.KyrgyzAlphabet

/**
 * 柯尔克孜语字符工具（纯函数，无副作用）。
 *
 * 字符集与键位映射严格遵循：
 * - GB21669-2008《信息技术 维吾尔文、哈萨克文、柯尔克孜文编码字符集》
 * - GB/T 31917-2015《信息技术 柯尔克孜文通用键盘字母数字区布局》（QWERTY 布局）
 * - GB/T 31921-2015《信息技术 基于数字键盘的柯尔克孜文字母布局》（九宫格布局）
 */
object KyrgyzCharacterUtils {

    /** GB/T 31917-2015 附录 A 标准柯尔克孜文字母表（30 个字母）。 */
    val ALL_LETTERS: Set<String> = KyrgyzAlphabet.LETTERS.toSet()

    /** 元音字母集合（GB 标准中的 8 个）。 */
    val VOWELS: Set<String> = setOf(
        "\u0627", // ا
        "\u06D5", // ە
        "\u06C5", // ۅ
        "\u06C7", // ۇ
        "\u06C9", // ۉ
        "\u0649", // ى
        "\u0626", // ئ
        "\u064A"  // ي
    )

    /** 辅音字母集合 = 全集 - 元音。 */
    val CONSONANTS: Set<String> = ALL_LETTERS - VOWELS

    /** 附加符号（fatha / kasra / damma / shadda）。 */
    val DIACRITICS: Set<String> = KyrgyzAlphabet.DIACRITICS.toSet()

    /** GB 标准标点符号。 */
    val PUNCTUATION: Set<String> = KyrgyzAlphabet.PUNCTUATION.toSet()

    /**
     * QWERTY 键位 -> 柯尔克孜字母的映射（GB/T 31917-2015 表 2 第 1 层）。
     * 与 [com.example.kyrgyzkeyboard.keyboard.KyrgyzKeyboardLayouts.DefaultLayout] 主键位一一对应。
     *
     * 行对应：`A`…`'` ↔ C01–C11，`Q`…`P` ↔ D01–D10，`Z`…`/` ↔ B01–B10。
     * 表 2 的 E00（`ـ` / `…`）无对应物理键位，不在此表内。
     */
    private val QWERTY_TO_KYRGYZ: Map<Char, String> = mapOf(
        // D 行 (D01-D10)
        'q' to "\u0686", // D01 چ
        'w' to "\u06CB", // D02 ۋ
        'e' to "\u06D5", // D03 ە
        'r' to "\u0631", // D04 ر
        't' to "\u062A", // D05 ت
        'y' to "\u064A", // D06 ي
        'u' to "\u06C7", // D07 ۇ
        'i' to "\u06AD", // D08 ڭ
        'o' to "\u0648", // D09 و
        'p' to "\u067E", // D10 پ
        // C 行 (C01-C11)
        'a' to "\u06BE", // C01 ھ
        's' to "\u0633", // C02 س
        'd' to "\u062F", // C03 د
        'f' to "\u0627", // C04 ا
        'g' to "\u06D5", // C05 ە
        'h' to "\u0649", // C06 ى
        'j' to "\u0642", // C07 ق
        'k' to "\u0643", // C08 ك
        'l' to "\u0644", // C09 ل
        ';' to "\u061B", // C10 ؛
        '\'' to "\u00BB", // C11 »
        // B 行 (B01-B10)
        'z' to "\u0632", // B01 ز
        'x' to "\u0634", // B02 ش
        'c' to "\u0639", // B03 ع
        'v' to "\u06C9", // B04 ۉ
        'b' to "\u0628", // B05 ب
        'n' to "\u0646", // B06 ن
        'm' to "\u0645", // B07 م
        ',' to "\u060C", // B08 ،
        '.' to "\u002E", // B09 .（无柯文字母）
        '/' to "\u0626"  // B10 ئ
    )

    /**
     * QWERTY Shift 层键位映射（GB/T 31917-2015 表 2 第 2 层）。
     * 表 2 未规定第 2 层的键，回落到第 1 层映射（见 [getKeyboardMapping]）。
     */
    private val QWERTY_TO_KYRGYZ_SHIFT: Map<Char, String> = mapOf(
        'f' to "\u0641",  // C04 第 2 层 ف
        'g' to "\u06AF",  // C05 第 2 层 گ
        'h' to "\u062D",  // C06 第 2 层 ح
        '\'' to "\u00AB", // C11 第 2 层 «
        '/' to "\u061F"   // B10 第 2 层 ؟
    )

    /**
     * 数字键盘键位映射（GB/T 31921-2015 表 1 标准）。
     * 数字键 -> 该键上的字符列表。
     */
    val DIGITAL_TO_KYRGYZ: Map<Char, List<String>> = mapOf(
        '1' to listOf("\u002E", "\u060C", "\u061B", "\u061F", "\u0021"), // . ، ؛ ؟ !
        '2' to listOf("\u0627", "\u0628", "\u0686", "\u0639"), // ا ب چ ع
        '3' to listOf("\u062F", "\u06D5", "\u0626", "\u0641"), // د ە ئ ف
        '4' to listOf("\u06AF", "\u062D", "\u0649"), // غ ح ى
        '5' to listOf("\u062C", "\u0643", "\u0644"), // ج ك ل
        '6' to listOf("\u0645", "\u0646", "\u0648", "\u06AD"), // م ن و ڭ
        '7' to listOf("\u067E", "\u0642", "\u0631", "\u0633"), // پ ق ر س
        '8' to listOf("\u062A", "\u06C7", "\u06C5", "\u06C9"), // ت ۇ ۅ ۉ
        '9' to listOf("\u06CB", "\u0634", "\u064A", "\u0632"), // ۋ ش ي ز
        '0' to listOf(" ", "\u0640", "\u2026", "\u00AB", "\u00BB") // 空格 ـ … « »
    )

    /** 单字符是否属于柯尔克孜字母表。 */
    fun isKyrgyzLetter(char: Char): Boolean =
        ALL_LETTERS.contains(char.toString())

    /** 单字符是否为元音。 */
    fun isVowel(char: Char): Boolean =
        VOWELS.contains(char.toString())

    /**
     * 阿拉伯写法文本规范化：
     * 1. 去除阿拉伯 tatweel（U+0640）拉长符
     * 2. 折叠连续空白
     * 3. 统一 Java/波斯 ي 变体到 U+06CC
     */
    fun normalizeArabicText(text: String): String {
        if (text.isEmpty()) return text
        val sb = StringBuilder(text.length)
        var lastWasSpace = false
        for (raw in text) {
            val ch = when (raw) {
                '\u0640' -> continue          // 忽略 tatweel
                '\u064A' -> '\u06CC'          // Arabic Yeh -> Farsi Yeh (统一形)
                else -> raw
            }
            if (ch.isWhitespace()) {
                if (!lastWasSpace) sb.append(' ')
                lastWasSpace = true
            } else {
                sb.append(ch)
                lastWasSpace = false
            }
        }
        return sb.toString().trim()
    }

    /**
     * 硬件键盘按键 -> 柯尔克孜字母。返回 null 表示无映射。
     * @param isShift 是否按下 Shift 键（使用第 2 层映射）
     */
    fun getKeyboardMapping(qwertyChar: Char, isShift: Boolean = false): String? {
        val lower = qwertyChar.lowercaseChar()
        return if (isShift) {
            QWERTY_TO_KYRGYZ_SHIFT[lower] ?: QWERTY_TO_KYRGYZ[lower]
        } else {
            QWERTY_TO_KYRGYZ[lower]
        }
    }

    /**
     * 数字键盘按键 -> 柯尔克孜字母。
     * @param index 该键上的字符索引（0 为默认）
     */
    fun getDigitalMapping(digitalChar: Char, index: Int = 0): String? {
        val chars = DIGITAL_TO_KYRGYZ[digitalChar] ?: return null
        return if (index in chars.indices) chars[index] else chars[0]
    }

    /**
     * 获取数字键上的所有字符列表。
     */
    fun getDigitalChars(digitalChar: Char): List<String>? {
        return DIGITAL_TO_KYRGYZ[digitalChar]
    }
}
